#!/usr/bin/env python3
import gzip
import hashlib
import io
import sys
import urllib.request


TRACKS = [
    (
        "Liver_lobe",
        "BSS01519",
        "https://filer2.niagads.org/Annotationtracks/EpiMap/ChromHMM/bed9/hg38/formatted_output_BSS01519_ENCODE_All_hg38.bed.gz",
        "da20c0c86c33f1fbfe3e1f2138a5258d",
    ),
    (
        "Middle_frontal_area_BA46",
        "BSS01271",
        "https://filer2.niagads.org/Annotationtracks/EpiMap/ChromHMM/bed9/hg38/formatted_output_BSS01271_Roadmap_2015_All_hg38.bed.gz",
        "ac7f07d1bb5468ddce406584a6c39cb3",
    ),
    (
        "Frontal_cortex",
        "BSS00369",
        "https://filer2.niagads.org/Annotationtracks/EpiMap/ChromHMM/bed9/hg38/formatted_output_BSS00369_ENCODE_All_hg38.bed.gz",
        "42e70ca6a65d6aa7b2e2054973d274ca",
    ),
    (
        "H1-hESC",
        "BSS00478",
        "https://filer2.niagads.org/Annotationtracks/EpiMap/ChromHMM/bed9/hg38/formatted_output_BSS00478_Roadmap_2015_All_hg38.bed.gz",
        "f22f14fff4268e5deee605f2786ac8db",
    ),
]

CHROM = "chr11"
# The stated browser interval is 1-based inclusive; the corresponding BED
# half-open interval is [124738680, 124738772).  The second target checks the
# plausible direct-as-BED interpretation for coordinate robustness.
TARGETS = [
    ("browser_1based_inclusive_to_BED", 124738680, 124738772),
    ("literal_numbers_as_BED", 124738681, 124738772),
]


def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": "Galaxy-EpiMap-interval-probe/1.0"})
    with urllib.request.urlopen(req, timeout=120) as response:
        return response.read()


def main(out_path):
    header = [
        "sample", "bss_id", "coordinate_interpretation", "query_chrom",
        "query_start_bed", "query_end_bed", "state_chrom", "state_start",
        "state_end", "chromhmm_state", "overlap_bp", "source_md5", "source_url",
    ]
    rows = []
    for sample, bss_id, url, expected_md5 in TRACKS:
        payload = fetch(url)
        observed_md5 = hashlib.md5(payload).hexdigest()
        if observed_md5 != expected_md5:
            raise RuntimeError(
                "%s checksum mismatch: expected %s observed %s"
                % (sample, expected_md5, observed_md5)
            )
        hits = {label: [] for label, _, _ in TARGETS}
        with gzip.GzipFile(fileobj=io.BytesIO(payload), mode="rb") as gz:
            for raw in gz:
                if not raw or raw.startswith(b"#"):
                    continue
                fields = raw.decode("utf-8").rstrip("\n").split("\t")
                if len(fields) < 4 or fields[0] != CHROM:
                    continue
                start, end = int(fields[1]), int(fields[2])
                for label, query_start, query_end in TARGETS:
                    overlap = max(0, min(end, query_end) - max(start, query_start))
                    if overlap:
                        hits[label].append((fields, overlap, query_start, query_end))
        for label, _, _ in TARGETS:
            if not hits[label]:
                raise RuntimeError("No overlapping state for %s under %s" % (sample, label))
            for fields, overlap, query_start, query_end in hits[label]:
                rows.append([
                    sample, bss_id, label, CHROM, str(query_start), str(query_end),
                    fields[0], fields[1], fields[2], fields[3], str(overlap),
                    observed_md5, url,
                ])
    with open(out_path, "w", encoding="utf-8") as out:
        out.write("\t".join(header) + "\n")
        for row in rows:
            out.write("\t".join(row) + "\n")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("usage: epimap_interval_probe.py OUTPUT.tsv")
    main(sys.argv[1])

